-- fudcourt's system of record (DR-040).
--
-- Postgres+TimescaleDB is the SINGLE system of record. Every writer — the Python
-- sync (tests/oracle/sync-live.py), the Rust crate (backend/sync) and the web
-- (frontend/web/src/server/db.ts) — reads and writes HERE. There is no
-- remote mirror and no second store; the DR-019 Turso/libSQL split is retired.
--
-- Types: TEXT -> text (the datetime columns stay 'YYYY-MM-DD HH:MM:SS' UTC
-- strings, so the boards render the stored value rather than a re-formatted
-- Date), REAL -> double precision, INTEGER PK -> integer GENERATED BY DEFAULT AS
-- IDENTITY (BY DEFAULT, not ALWAYS, so a writer may preserve an explicit id).
CREATE EXTENSION IF NOT EXISTS timescaledb; -- trusted ext; create_hypertable() below needs it on a clean database (QA 2026-10-09)
CREATE TABLE IF NOT EXISTS accounts (
  code      text PRIMARY KEY,
  name      text NOT NULL,
  type      text NOT NULL,
  statement text NOT NULL
);

CREATE TABLE IF NOT EXISTS assets (
  id         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  chain      text NOT NULL,
  asset      text NOT NULL,
  quantity   double precision,
  value_usd  double precision,
  share_pct  double precision,
  wallet     text,
  updated_at text DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);
-- Idempotency key for the board upsert: the Rust sync (apps/reconciler,
-- src/persistence/db.rs) inserts with ON CONFLICT (wallet, chain, asset)
-- DO UPDATE and PLANS against this index; the Python sync replaces the table
-- wholesale (DELETE + INSERT). Wallet is always set, so plain UNIQUE holds.
CREATE UNIQUE INDEX IF NOT EXISTS assets_wallet_chain_asset
  ON assets (wallet, chain, asset);

CREATE TABLE IF NOT EXISTS journal (
  id             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  date           text NOT NULL,
  entry_code     text NOT NULL,
  debit_account  text,
  credit_account text,
  memo           text,
  amount         double precision,
  status         text DEFAULT 'Posted',
  created_at     text DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

CREATE TABLE IF NOT EXISTS ledger (
  id           integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_code text NOT NULL,
  account_name text NOT NULL,
  side         text NOT NULL,
  balance      double precision NOT NULL DEFAULT 0,
  currency     text DEFAULT 'USD'
);

CREATE TABLE IF NOT EXISTS trades (
  id       integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  date     text NOT NULL,
  venue    text,
  symbol   text,
  side     text,
  quantity double precision,
  price    double precision,
  pnl      double precision,
  status   text
);

CREATE TABLE IF NOT EXISTS transactions (
  id         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  date       text NOT NULL,
  chain      text NOT NULL,
  asset      text,
  event      text NOT NULL,
  amount_usd double precision,
  direction  text,
  hash       text,
  url        text,
  source     text,
  created_at text DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  memo       text,
  wallet_to  text,
  venue_id   text,
  trade_id   text
);

CREATE TABLE IF NOT EXISTS venues (
  id   text PRIMARY KEY,
  name text NOT NULL,
  type text NOT NULL
);

CREATE TABLE IF NOT EXISTS wallets (
  address    text PRIMARY KEY,
  label      text,
  chain      text,
  monitored  integer DEFAULT 1,
  created_at text DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  alias      text,
  emoji      text DEFAULT '💰',
  color      text DEFAULT '#3ddc97',
  notes      text
);

-- TimescaleDB time series. Every `assets` observation — inserted by the sync, a
-- route or an operator — is appended here by the `assets_snapshot` trigger below,
-- so "what was I worth at time T" stops being a table scan of the live table and
-- becomes a hypertable lookup. `assets` above stays the latest-state table the
-- board reads.
CREATE TABLE IF NOT EXISTS asset_history (
  ts        timestamptz NOT NULL,
  chain     text NOT NULL,
  asset     text NOT NULL,
  wallet    text,
  quantity  double precision,
  value_usd double precision,
  share_pct double precision
);

SELECT create_hypertable('asset_history', 'ts', if_not_exists => TRUE);
CREATE INDEX IF NOT EXISTS asset_history_asset_ts ON asset_history (asset, ts DESC);
-- The loader upserts on this key. `wallet` is nullable in the source, and two
-- NULLs never conflict in Postgres, so the index coalesces it: without that,
-- every re-run would append a duplicate row for a wallet-less asset.
CREATE UNIQUE INDEX IF NOT EXISTS asset_history_snapshot
  ON asset_history (ts, chain, asset, (coalesce(wallet, '')));

-- The snapshot is a TRIGGER, not application code (DR-040): the writer only has
-- to INSERT into `assets` and the time series takes care of itself, so the Python
-- sync, the Rust crate and a manual `psql` insert all snapshot identically. The
-- sync replaces `assets` wholesale (DELETE then INSERT) and a row trigger fires
-- per inserted row, so that is exactly one snapshot per observation. The ts is the
-- observation's own `updated_at`: a naive UTC wall-clock string stays as written, an ISO string carrying Z or a numeric offset becomes the instant it names (QA 2026-10-09); the
-- ON CONFLICT matches asset_history_snapshot so a re-insert at the same ts updates
-- in place rather than duplicating.
CREATE OR REPLACE FUNCTION assets_snapshot() RETURNS trigger AS $$
BEGIN
  INSERT INTO asset_history (ts, chain, asset, wallet, quantity, value_usd, share_pct)
  VALUES (COALESCE(CASE WHEN NULLIF(NEW.updated_at, '') ~ '(Z|[+-][0-9]{2}(:[0-9]{2})?|[+-][0-9]{4})$' THEN NULLIF(NEW.updated_at, '')::timestamptz ELSE NULLIF(NEW.updated_at, '')::timestamp AT TIME ZONE 'UTC' END, now()),
          NEW.chain, NEW.asset, NEW.wallet, NEW.quantity, NEW.value_usd, NEW.share_pct)
  ON CONFLICT (ts, chain, asset, (coalesce(wallet, ''))) DO UPDATE
    SET quantity  = EXCLUDED.quantity,
        value_usd = EXCLUDED.value_usd,
        share_pct = EXCLUDED.share_pct;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS assets_snapshot_trg ON assets;
CREATE TRIGGER assets_snapshot_trg AFTER INSERT ON assets
  FOR EACH ROW EXECUTE FUNCTION assets_snapshot();

-- And the same for the market side: a compact price series the boards can chart
-- without re-hitting a provider for history. Written by the price sampler.
CREATE TABLE IF NOT EXISTS price_history (
  ts     timestamptz NOT NULL,
  symbol text NOT NULL,
  source text NOT NULL,
  price  double precision NOT NULL
);

SELECT create_hypertable('price_history', 'ts', if_not_exists => TRUE);
CREATE UNIQUE INDEX IF NOT EXISTS price_history_symbol_ts_source
  ON price_history (symbol, ts, source);

-- Retention: 90 days, beyond which the boards never look. It is a plain DELETE in
-- tests/oracle/sync-live.py (after the sync writes) rather than
-- add_retention_policy(), because the retention-policy API is Timescale License,
-- not Apache-2 (this build refuses it: "not supported under the current 'apache'
-- license"). A DELETE of <= a few thousand rows per day needs no policy engine,
-- and keeping the install Apache-only keeps the licence story as simple as the
-- rest of the stack.
--
-- Durable canonical identity (DR-036). The canonical id space lives code-side in
-- backend/api/internal/markets/reference (minted, opaque) and ships as the artifact
-- shared/contracts/data/reference.json. This is its SQL half: the published
-- (provider, provider_id) -> canonical_id resolution table, so a database consumer
-- can resolve through a canonical id instead of a symbol. It is ADDITIVE and
-- UNWIRED: nothing reads it yet (no FK, no column on any money-bearing row, no
-- runtime caller), and the loader that fills it is
-- backend/api/internal/markets/reference/loader.go. The table is a derived CACHE of
-- the artifact, not a second source: the loader UPSERTs the artifact's rows and
-- prunes any provider key it no longer sees, so the artifact stays the single source
-- of truth (no id is re-derived here).
--
-- Types follow the artifact where a column has a source: text for every id and key
-- (ids are opaque strings, never parsed), text for `loaded_at` for the same reason as
-- the datetime columns above (a dump round-trips as the same 'YYYY-MM-DD HH:MM:SS'
-- string rather than re-rendering through a Date), and boolean for the miss table's
-- `known_absence`. No money is stored here: every column is an identifier, a
-- namespace label, a timestamp string, or the miss table's prose.
CREATE TABLE IF NOT EXISTS canonical_reference (
  provider     text NOT NULL,
  provider_id  text NOT NULL,
  canonical_id text NOT NULL,
  kind         text NOT NULL,
  loaded_at    text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY (provider, provider_id),
  -- `kind` must agree with the id's own prefix, so an id stored under the wrong
  -- namespace is refused at write time instead of producing a wrong join. That makes
  -- `kind` redundant-but-ENFORCED rather than merely advisory: the prefix is a string,
  -- and this CHECK is the database-level form of the same invariant (the loader's
  -- validateDocument checks it too, but the table must not rely on its writer for its
  -- own integrity). `LIKE kind || ':%'` is valid because the pattern is a plain
  -- concatenation — no LIKE metacharacters appear in a kind.
  --
  -- The constraint is NAMED and duplicated in the guarded DO block below. That is
  -- not belt-and-braces for its own sake: `CREATE TABLE IF NOT EXISTS` is a NO-OP
  -- when the table already exists, so an inline CHECK only ever lands at FIRST
  -- creation. This file is designed to be re-appliable (every statement is
  -- IF NOT EXISTS), and a plain-psql applier whose table predates this DDL would
  -- otherwise run the whole file to completion WITHOUT the invariant — silently.
  -- The DO block re-adds the constraint (only when absent, matched by name) so a
  -- re-applied schema still refuses a bad `kind`. The name is what makes it
  -- idempotent: without it `ALTER TABLE ... ADD CONSTRAINT` is a second,
  -- auto-named constraint and every re-apply adds another.
  CONSTRAINT canonical_reference_kind_prefix CHECK (canonical_id LIKE kind || ':%')
);
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint
                  WHERE conrelid = 'canonical_reference'::regclass
                    AND conname  = 'canonical_reference_kind_prefix') THEN
    ALTER TABLE canonical_reference
      ADD CONSTRAINT canonical_reference_kind_prefix
      CHECK (canonical_id LIKE kind || ':%');
  END IF;
END
$$;
-- `kind` is the canonical_id's namespace. The values the loader writes today are
-- exactly the EntityKinds the reference registry mints ('asset' | 'chain' | 'token'
-- | 'venue') because it derives its accepted set from `EntityKinds`. The DDL
-- deliberately does NOT pin that closed set a second time: the CHECK above enforces
-- the structural invariant (kind agrees with the id's prefix), while "which
-- namespaces exist" stays owned by the registry, so adding one does not become a
-- DDL migration. 'instrument' is therefore not rejected by the table — it simply
-- cannot arrive, because instruments are minted
-- (`backend/api/internal/markets/instruments/canonical.go`) but are absent from
-- `reference.json`, and the loader refuses any namespace outside `EntityKinds`.
CREATE INDEX IF NOT EXISTS canonical_reference_canonical_id
  ON canonical_reference (canonical_id);
CREATE INDEX IF NOT EXISTS canonical_reference_kind
  ON canonical_reference (kind);
-- Known-but-unresolved provider identifiers (the artifact's `misses`), stored as
-- their own rows so a consumer's left join sees a NULL target instead of assuming
-- the key is absent from upstream. `known_absence` marks one the tree itself
-- stores lossily (the `SPL:<mint6>` truncation) versus one simply not registered.
CREATE TABLE IF NOT EXISTS canonical_reference_miss (
  provider      text NOT NULL,
  provider_id   text NOT NULL,
  kind          text NOT NULL,
  reason        text NOT NULL,
  reported_as   text NOT NULL DEFAULT '',
  known_absence boolean NOT NULL DEFAULT false,
  loaded_at     text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY (provider, provider_id)
);

-- Admin-editable platform settings, key/value. The site reads live config from
-- here so an admin changes the Discord wiring (guild + role mapping) from the
-- panel without editing .env or restarting. The same-named env vars are only the
-- boot default; the api overlays a stored value on top of them
-- (apps/api/settings.go, discordClient.effective). Secrets stay in the
-- environment and are never stored here.
CREATE TABLE IF NOT EXISTS settings (
  key        text PRIMARY KEY,
  value      text NOT NULL,
  updated_at text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

-- Moderation case log. One row per moderation action the bot performs (and,
-- later, the dashboard). The Discord bot is a zero-dependency Bun program with
-- no Postgres driver, so it writes here through the loopback api
-- (apps/api/moderation_cases.go), the same hop it reads `settings` through.
--
-- case_number is the human-facing number shown in `!case 42` and the dashboard:
-- a dedicated sequence, so two concurrent inserts can never collide on it
-- (unlike MAX()+1, which under READ COMMITTED can hand the same number to two
-- transactions). The surrogate `id` stays the stable ordering key.
--
-- Snowflake ids are text (never a numeric type a JS client could lose precision
-- on). Timestamps are 'YYYY-MM-DD HH:MM:SS' UTC strings, matching `settings`.
CREATE SEQUENCE IF NOT EXISTS moderation_case_number_seq;

CREATE TABLE IF NOT EXISTS moderation_cases (
  id                integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  case_number       bigint NOT NULL UNIQUE DEFAULT nextval('moderation_case_number_seq'),
  guild_id          text NOT NULL,
  action            text NOT NULL,
  target_user_id    text NOT NULL,
  moderator_user_id text NOT NULL,
  reason            text NOT NULL DEFAULT '',
  duration_seconds  integer,
  source            text NOT NULL DEFAULT 'slash',
  status            text NOT NULL DEFAULT 'closed',
  created_at        text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  expires_at        text,
  updated_at        text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

-- The two read patterns the bot and dashboard actually use: a member's history
-- (guild + target, newest first) and the recent-cases feed (guild, newest
-- first). Both walk the primary key descending, so one composite index each
-- covers them without a separate id index.
CREATE INDEX IF NOT EXISTS moderation_cases_target_idx ON moderation_cases (guild_id, target_user_id, id DESC);
CREATE INDEX IF NOT EXISTS moderation_cases_recent_idx ON moderation_cases (guild_id, id DESC);

--
-- automod_rules — the operator-authored AutoMod rule set (apps/api/automod_rules.go,
-- apps/discord-bot/src/automod/*). A rule is DATA, not code: matchers, actions and
-- exemptions are stored as jsonb so a rule's shape can grow without a migration,
-- while the fields an admin lists or sorts on (name, enabled, priority, event) stay
-- real columns. The bot reads the validated rows over the loopback hop and never
-- touches Postgres directly (it carries no driver), the same pattern as `settings`
-- and `moderation_cases`.
--
-- The api re-validates every row (apps/discord-bot/src/automod/rules.ts is the
-- reference shape) before it reaches the message hot path, so a malformed row can
-- never crash the bot: it is skipped and logged.
CREATE TABLE IF NOT EXISTS automod_rules (
  id              integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  guild_id        text NOT NULL,
  name            text NOT NULL,
  enabled         boolean NOT NULL DEFAULT true,
  priority        integer NOT NULL DEFAULT 0,
  event           text NOT NULL DEFAULT 'message',   -- 'message' | 'member_join'
  matchers        jsonb NOT NULL DEFAULT '[]'::jsonb, -- [{type,threshold?,values?,pattern?}]
  actions         jsonb NOT NULL DEFAULT '[]'::jsonb, -- ["delete","timeout",...]
  exempt_roles    text[] NOT NULL DEFAULT '{}',
  exempt_users    text[] NOT NULL DEFAULT '{}',
  exempt_channels text[] NOT NULL DEFAULT '{}',
  cooldown_seconds integer NOT NULL DEFAULT 0,
  timeout_seconds  integer,
  role_id          text,
  created_at      text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  updated_at      text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

-- The bot's load is "every enabled rule for this guild, highest priority first";
-- one composite index covers it without a separate guild index.
CREATE INDEX IF NOT EXISTS automod_rules_guild_idx ON automod_rules (guild_id, enabled, priority DESC, id);

--
-- log_destinations — where the bot sends its Discord ACTIVITY logs (apps/api/logging.go,
-- apps/discord-bot/src/logging/*). One row per (guild, category): a category is a
-- class of activity (message, member, role, voice, channel, moderation, automod),
-- and the channel it is routed to. The bot reads the map over the loopback hop and
-- never touches Postgres directly, the same pattern as `settings`/`automod_rules`.
--
-- A category with no row (or a disabled row) is simply not logged — an operator
-- opts a category in by pointing it at a channel. That is what lets #mod-logs,
-- #message-logs and #join-logs be separate destinations instead of one firehose.
CREATE TABLE IF NOT EXISTS log_destinations (
  guild_id   text NOT NULL,
  category   text NOT NULL,
  channel_id text NOT NULL,
  enabled    boolean NOT NULL DEFAULT true,
  updated_at text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY (guild_id, category)
);

--
-- audit_logs — changes to the BOT ITSELF (apps/api/logging.go), as opposed to the
-- Discord activity in `log_destinations`. One row per mutation: who did it, what
-- changed, and the structured before/after (jsonb), so the dashboard can show an
-- accountable history of every settings/rule/feed/permission edit.
--
-- before/after are jsonb and nullable: a create has no `before`, a delete has no
-- `after`. actor_id is the dashboard user's Discord id (or the bot id for a
-- system/bot-originated change). Snowflakes are text; timestamps match `settings`.
CREATE TABLE IF NOT EXISTS audit_logs (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  guild_id      text NOT NULL,
  actor_id      text NOT NULL DEFAULT '',
  actor_name    text NOT NULL DEFAULT '',
  action        text NOT NULL,
  resource_type text NOT NULL,
  resource_id   text NOT NULL DEFAULT '',
  before        jsonb,
  after         jsonb,
  source        text NOT NULL DEFAULT 'dashboard',
  created_at    text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

-- The two read patterns the dashboard uses: the recent feed (guild, newest first)
-- and one resource's history (guild + type + id, newest first). Both walk the
-- primary key descending, so one composite index each covers them.
CREATE INDEX IF NOT EXISTS audit_logs_recent_idx ON audit_logs (guild_id, id DESC);
CREATE INDEX IF NOT EXISTS audit_logs_resource_idx ON audit_logs (guild_id, resource_type, resource_id, id DESC);

--
-- welcome_configs — the welcome/goodbye messages (apps/api/community.go,
-- apps/discord-bot/src/community/*). One row per guild: the bot reads it over the
-- loopback hop like every other config, so an operator edit lands with no restart.
--
-- A message may be a channel post and/or a DM, and each may be plain text and/or
-- an embed. `*_message` carries the template ({user}, {server}, {member_count}, …);
-- `*_embed` is a partial Discord embed (title/description/color/…) whose string
-- fields are themselves templated. Absent/disabled = that surface is not sent.
CREATE TABLE IF NOT EXISTS welcome_configs (
  guild_id          text PRIMARY KEY,
  join_enabled      boolean NOT NULL DEFAULT false,
  join_channel_id   text NOT NULL DEFAULT '',
  join_message      text NOT NULL DEFAULT '',
  join_embed        jsonb,
  join_dm           boolean NOT NULL DEFAULT false,
  join_dm_message   text NOT NULL DEFAULT '',
  leave_enabled     boolean NOT NULL DEFAULT false,
  leave_channel_id  text NOT NULL DEFAULT '',
  leave_message     text NOT NULL DEFAULT '',
  leave_embed       jsonb,
  updated_at        text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')
);

--
-- autorole_rules — roles granted automatically (apps/api/community.go,
-- apps/discord-bot/src/community/*). `kind` is how the grant is triggered:
--   on_join           — immediately on join (delay_seconds may still apply)
--   after_duration    — delay_seconds after join (the bot schedules the grant)
--   after_verification— once the member passes verification (a state the bot tracks)
-- `applies_to` narrows the rule: all members, humans only, or bots only. One row
-- per (guild, role, kind); `enabled`/`priority` order application. Discord role
-- hierarchy is validated before a grant is attempted (a role above the bot is
-- never attempted) and a failed grant is persisted to `role_assignments`.
CREATE TABLE IF NOT EXISTS autorole_rules (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  guild_id      text NOT NULL,
  role_id       text NOT NULL,
  kind          text NOT NULL DEFAULT 'on_join',
  delay_seconds integer NOT NULL DEFAULT 0,
  applies_to    text NOT NULL DEFAULT 'all',
  enabled       boolean NOT NULL DEFAULT true,
  priority      integer NOT NULL DEFAULT 0,
  created_at    text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  updated_at    text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT autorole_rules_kind_chk CHECK (kind IN ('on_join', 'after_duration', 'after_verification')),
  CONSTRAINT autorole_rules_applies_chk CHECK (applies_to IN ('all', 'human', 'bot'))
);
CREATE UNIQUE INDEX IF NOT EXISTS autorole_rules_guild_role_kind_uniq
  ON autorole_rules (guild_id, role_id, kind);
CREATE INDEX IF NOT EXISTS autorole_rules_guild_idx
  ON autorole_rules (guild_id, enabled, priority DESC, id);

--
-- role_panels — a self-serve role menu (apps/api/community.go,
-- apps/discord-bot/src/community/*). The panel is posted once to `channel_id` as
-- `message_id` (a bot-authored message with buttons/selects/reactions); members
-- pick roles by interacting. `mode` is the selection semantics:
--   toggle    — each option is an independent on/off (buttons)
--   single    — at most one option from the panel (radio)
--   multiple  — any number of options, no exclusivity (select menu, multi)
--   exclusive — options sharing an `exclusive_group` are mutually exclusive
-- `id` is an operator-chosen slug (e.g. "colors"), not a surrogate key: it is
-- stable across DB resets and is embedded verbatim in the Discord custom-id
-- `rp:<id>:<roleId>`, so it must be text (a bigint would also work but the bot
-- and dashboard both read/write it as a string). The key is COMPOSITE
-- `(guild_id, id)`: a slug is unique per guild, and `replacePanels` rewrites one
-- guild's set at a time (DELETE … WHERE guild_id), so a global PK on `id` alone
-- would collide the moment two guilds used the same slug. `style` on an option
-- is the button style / emoji-reaction hint. `kind` selects the control the bot
-- renders: reaction, button or select. `exclusive_group` lives on the OPTION
-- (not the panel): options sharing a non-empty group are mutually exclusive, so
-- the group is a property of each option, not of the menu as a whole.
CREATE TABLE IF NOT EXISTS role_panels (
  id              text NOT NULL,
  guild_id        text NOT NULL,
  channel_id      text NOT NULL,
  message_id      text NOT NULL DEFAULT '',
  title           text NOT NULL DEFAULT '',
  description     text NOT NULL DEFAULT '',
  kind            text NOT NULL DEFAULT 'button',
  mode            text NOT NULL DEFAULT 'toggle',
  enabled         boolean NOT NULL DEFAULT true,
  created_at      text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  updated_at      text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT role_panels_pkey PRIMARY KEY (guild_id, id),
  CONSTRAINT role_panels_kind_chk CHECK (kind IN ('reaction', 'button', 'select')),
  CONSTRAINT role_panels_mode_chk CHECK (mode IN ('toggle', 'single', 'multiple', 'exclusive'))
);
CREATE INDEX IF NOT EXISTS role_panels_guild_idx ON role_panels (guild_id, enabled, id);
CREATE INDEX IF NOT EXISTS role_panels_message_idx ON role_panels (message_id);

CREATE TABLE IF NOT EXISTS role_panel_options (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  guild_id        text NOT NULL,
  panel_id        text NOT NULL,
  role_id         text NOT NULL,
  label           text NOT NULL DEFAULT '',
  emoji           text NOT NULL DEFAULT '',
  style           text NOT NULL DEFAULT 'secondary',
  position        integer NOT NULL DEFAULT 0,
  exclusive_group text NOT NULL DEFAULT '',
  CONSTRAINT role_panel_options_panel_fk FOREIGN KEY (guild_id, panel_id)
    REFERENCES role_panels (guild_id, id) ON DELETE CASCADE,
  CONSTRAINT role_panel_options_style_chk CHECK (style IN ('primary', 'secondary', 'success', 'danger')),
  CONSTRAINT role_panel_options_panel_role_uniq UNIQUE (guild_id, panel_id, role_id)
);
CREATE INDEX IF NOT EXISTS role_panel_options_panel_idx ON role_panel_options (guild_id, panel_id, position, id);

--
-- role_assignments — an auditable record of every automatic role grant/revoke
-- (apps/discord-bot/src/community/*). Successes make the "who got what" story
-- replayable; failures persist the reason so an operator can see a role the bot
-- could not grant (usually hierarchy) instead of it failing silently. `source`
-- is the trigger (autorole, panel, verification); `status` is ok|failed.
CREATE TABLE IF NOT EXISTS role_assignments (
  id         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  guild_id   text NOT NULL,
  user_id    text NOT NULL,
  role_id    text NOT NULL,
  action     text NOT NULL DEFAULT 'add',
  source     text NOT NULL DEFAULT 'autorole',
  status     text NOT NULL DEFAULT 'ok',
  error      text NOT NULL DEFAULT '',
  created_at text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT role_assignments_action_chk CHECK (action IN ('add', 'remove')),
  CONSTRAINT role_assignments_status_chk CHECK (status IN ('ok', 'failed'))
);
CREATE INDEX IF NOT EXISTS role_assignments_guild_idx ON role_assignments (guild_id, id DESC);
CREATE INDEX IF NOT EXISTS role_assignments_user_idx ON role_assignments (guild_id, user_id, id DESC);

--
-- custom_commands — declarative operator-authored commands (apps/api/customcommands.go,
-- apps/discord-bot/src/customcommands/*). A member types the configured prefix
-- (settings key `discord.prefix`, default `!`) followed by `name` (or an alias)
-- and the bot posts the configured response. DELIBERATELY declarative: the
-- response is DATA (text + an optional embed), never code. There is no scripting
-- surface — no shell, no JavaScript, no SQL — so a custom command can never
-- execute anything; it can only render a template and send it. `responses` is a
-- jsonb array of {text, embed}; more than one entry is a RANDOM response (one is
-- picked per invocation), so a single column covers both the fixed and the
-- randomized case.
-- `name` is the trigger WITHOUT the prefix (e.g. "rules"), stored lowercase; the
-- key is (guild_id, name). `aliases` are extra triggers for the same command.
-- `allowed_roles`/`allowed_channels` are ALLOW-LISTS: empty means "anyone / any
-- channel"; a non-empty list requires the member to hold at least one listed role
-- (or the message to be in a listed channel), otherwise the command is ignored.
-- `cooldown_seconds` is a per-(command, member) throttle; `delete_trigger`
-- removes the invoking message; `reply` posts as a Discord reply to it; `dm`
-- sends the response by direct message instead of to the channel.
CREATE TABLE IF NOT EXISTS custom_commands (
  id               bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  guild_id         text NOT NULL,
  name             text NOT NULL,
  aliases          text[] NOT NULL DEFAULT '{}',
  responses        jsonb NOT NULL DEFAULT '[]'::jsonb,
  allowed_roles    text[] NOT NULL DEFAULT '{}',
  allowed_channels text[] NOT NULL DEFAULT '{}',
  cooldown_seconds integer NOT NULL DEFAULT 0,
  delete_trigger   boolean NOT NULL DEFAULT false,
  reply            boolean NOT NULL DEFAULT true,
  dm               boolean NOT NULL DEFAULT false,
  enabled          boolean NOT NULL DEFAULT true,
  created_at       text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  updated_at       text NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  CONSTRAINT custom_commands_guild_name_uniq UNIQUE (guild_id, name),
  CONSTRAINT custom_commands_cooldown_chk CHECK (cooldown_seconds >= 0 AND cooldown_seconds <= 86400)
);
CREATE INDEX IF NOT EXISTS custom_commands_guild_idx ON custom_commands (guild_id, enabled, name);

--
-- jobs — the durable job queue the worker (apps/discord-worker) runs. Postgres is
-- the system of record: a queued job survives a worker crash, a restart and a
-- redeploy. Claiming is transactional (`FOR UPDATE SKIP LOCKED`), so two workers
-- can never claim the same row, and no lock is held while a job body runs.
--
-- The queue is DELIBERATELY generic. Phase 10's `scheduled_jobs` rows are the
-- *definitions* (a cron/interval rule) and each firing enqueues an execution
-- here; phase 11 enqueues feed polls the same way. `kind` names the handler and
-- `dedupe_key` is the caller's deterministic execution identity, so a re-enqueue
-- of the same logical work collides on the unique key instead of running twice —
-- idempotency enforced by the database, not by an application-level check.
--
-- `attempts` is bumped AT CLAIM TIME, never at completion, so a worker that
-- crashes mid-job still burns an attempt and a poisoned job eventually reaches
-- `dead` instead of looping forever.
CREATE TABLE IF NOT EXISTS jobs (
  id            bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  guild_id      text NOT NULL DEFAULT '',
  kind          text NOT NULL,
  dedupe_key    text NOT NULL,
  payload       jsonb NOT NULL DEFAULT '{}'::jsonb,
  run_at        timestamptz NOT NULL DEFAULT now(),
  status        text NOT NULL DEFAULT 'pending',
  attempts      integer NOT NULL DEFAULT 0,
  max_attempts  integer NOT NULL DEFAULT 5,
  locked_by     text,
  locked_at     timestamptz,
  last_error    text,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT jobs_status_chk CHECK (status IN ('pending','running','done','failed','dead')),
  CONSTRAINT jobs_attempts_chk CHECK (attempts >= 0 AND attempts <= max_attempts),
  CONSTRAINT jobs_identity_uniq UNIQUE (guild_id, kind, dedupe_key)
);
-- The claim path only ever looks at claimable rows, so the index is partial.
CREATE INDEX IF NOT EXISTS jobs_claim_idx ON jobs (run_at) WHERE status = 'pending';
-- The stale-claim reaper only ever looks at running rows.
CREATE INDEX IF NOT EXISTS jobs_reap_idx ON jobs (locked_at) WHERE status = 'running';
CREATE INDEX IF NOT EXISTS jobs_kind_idx ON jobs (guild_id, kind, status, id DESC);

--
-- job_runs — one row per execution ATTEMPT. This is the history that answers
-- "did this run, how many times, and why did it fail", and the raw material for
-- the dashboard's job view. `outcome` distinguishes a retryable failure (the job
-- goes back to `pending` with backoff) from a permanent one (straight to `dead`),
-- which is what makes "do not retry permanent errors forever" auditable.
-- 'outcome' is NULL while an attempt is in flight: a worker that dies mid-job
-- leaves the row open, and the stale-claim reaper closes it as 'crashed'. That is
-- what makes "the worker crashed after claiming" observable instead of silent.
CREATE TABLE IF NOT EXISTS job_runs (
  id           bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  job_id       bigint NOT NULL REFERENCES jobs(id) ON DELETE CASCADE,
  attempt      integer NOT NULL,
  worker       text NOT NULL,
  outcome      text,
  error        text,
  started_at   timestamptz NOT NULL DEFAULT now(),
  finished_at  timestamptz,
  CONSTRAINT job_runs_outcome_chk CHECK (
    outcome IS NULL OR outcome IN ('succeeded','retryable','permanent','crashed')
  )
);
CREATE INDEX IF NOT EXISTS job_runs_job_idx ON job_runs (job_id, attempt DESC);
-- The reaper looks for runs still open, and only for jobs it is reclaiming.
CREATE INDEX IF NOT EXISTS job_runs_open_idx ON job_runs (job_id) WHERE outcome IS NULL;
